{"file_path":"src/engine.js","content":"// Runs parsed policies, routes and events through the rate limiter simulation.

class BucketPolicy {
  constructor(def) {
    this.capacity = def.capacity
    this.refill = def.refill
    this.per = def.per
    this.states = new Map()
  }

  advance(key, tick) {
    let state = this.states.get(key)
    const capacityScaled = this.capacity * this.per
    if (!state) {
      state = { tokensScaled: capacityScaled, lastTick: tick }
      this.states.set(key, state)
      return
    }
    const delta = tick - state.lastTick
    if (delta > 0n) {
      state.tokensScaled += this.refill * delta
      if (state.tokensScaled > capacityScaled) state.tokensScaled = capacityScaled
      state.lastTick = tick
    }
  }

  allow(key) {
    const state = this.states.get(key)
    return state.tokensScaled >= this.per
  }

  record(key) {
    const state = this.states.get(key)
    state.tokensScaled -= this.per
  }
}

class WindowPolicy {
  constructor(def) {
    this.limit = def.limit
    this.span = def.span
    this.states = new Map()
  }

  advance(key, tick) {
    let state = this.states.get(key)
    if (!state) {
      state = { ticks: [] }
      this.states.set(key, state)
    }
    const cutoff = tick - this.span
    while (state.ticks.length > 0 && state.ticks[0] <= cutoff) {
      state.ticks.shift()
    }
  }

  allow(key) {
    const state = this.states.get(key)
    return state.ticks.length < this.limit
  }

  record(key, tick) {
    const state = this.states.get(key)
    state.ticks.push(tick)
  }
}

export class Engine {
  constructor(policies, routes) {
    this.instances = new Map()
    for (const [name, def] of policies) {
      this.instances.set(name, def.type === 'bucket' ? new BucketPolicy(def) : new WindowPolicy(def))
    }
    this.routes = [...routes.entries()]
      .map(([prefix, policyNames]) => ({ prefix, policyNames }))
      .sort((a, b) => b.prefix.length - a.prefix.length)
  }

  routeFor(key) {
    for (const route of this.routes) {
      if (key.startsWith(route.prefix)) return route
    }
    return null
  }

  process(tick, key) {
    const route = this.routeFor(key)
    if (!route) return { allow: true }

    for (const name of route.policyNames) {
      this.instances.get(name).advance(key, tick)
    }

    let denyPolicy = null
    for (const name of route.policyNames) {
      if (!this.instances.get(name).allow(key)) {
        denyPolicy = name
        break
      }
    }

    if (denyPolicy !== null) {
      return { allow: false, policy: denyPolicy }
    }

    for (const name of route.policyNames) {
      this.instances.get(name).record(key, tick)
    }
    return { allow: true }
  }
}
"}

