    this.per = def.per
    this.states = new Map()
  }

  advance(key, tick) {
    let state = this.states.get(key)
    const capacityScaled = this.capacity * this.per
    if (!state) {
      state = { tokensScaled: capacityScaled, lastTick: tick }
      this.states.set(key, state)
      return
    }
    const delta = tick - state.lastTick
